function DelayFollow:__init()
    self.controller = nil
end



function DelayFollow:__delete()
end


function DelayFollow:Awake()
    self.transform = self.controller.gameObject.transform
    ---
    assert( self.follow  )
    -- params ---:
    self.radius = LuaParametersReader.Read( self.params, "radius", LuaParametersReader.Type.Float ) -- float
    self.colliderRadius = LuaParametersReader.Read( self.params, "colliderRadius", LuaParametersReader.Type.Float ) -- float
    assert( self.radius and self.colliderRadius )
    self.radius = Mathf.Max( self.radius, 0.1 ) 
    self.colliderRadius = Mathf.Max( self.colliderRadius, 0.1 ) 
    self.sqrRadius =  self.radius * self.radius
    --- 
    self.transform.position = self.follow.position
end




function DelayFollow:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
end


function DelayFollow:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


function DelayFollow:Update()
    if DreamSpaceStates.IsDelayFollowUpdateActive ~= true then 
        return
    end
    ---
    local inverseOffset = self.transform.position - self.follow.position
    if inverseOffset.sqrMagnitude > self.sqrRadius then
        --print( "DelayFollow 开始跟随" )
        self.transform.position = self.follow.position + inverseOffset.normalized * self.radius    
    end
end

-- =========================================== Self ================================================ --



function DelayFollow:Distance( othPos )
    return ((othPos - self.transform.position).magnitude - self.colliderRadius)
end




return DelayFollow
